const judges = await parallel([0, 1, 2].map(i => () => agent(`${CONTEXT}\nYou are judge ${i + 1} of 3. Score each design 0-10 on: completeness (every SIMPLE cli/both row placed once; all MEDIUM/HARD/CLOSED/DEFERRED dispositioned), dependencyCorrectness (against the CLI reality facts), implementability (each batch is one Codex run + one reviewable PR), syncCoherence (the sync design actually propagates the fields and respects D20), approverFriction. Verify at least five specific claims per design against files under ${CLI} yourself. Pick a winner and say what to graft from the others.\n\nDESIGNS:\n${JSON.stringify(validDesigns)}\n\nCLI REALITY + SEAM + DECISIONS:\n${JSON.stringify({ cli: E['cli-reality'], seam: E['desktop-seam'], m6: E['m6-and-decisions'] })}`, { label: `judge:${i + 1}`, phase: 'Design', schema: JUDGE_SCHEMA, effort: 'high' })))
const votes = judges.filter(Boolean)
const tally = {}
for (const v of votes) tally[v.winner] = (tally[v.winner] || 0) + 1
const winnerLens = Object.entries(tally).sort((a, b) => b[1] - a[1])[0]?.[0] || validDesigns[0].lens
const winner = validDesigns.find(d => d.lens === winnerLens) || validDesigns[0]
log(`Judges: ${JSON.stringify(tally)} → winner ${winner.lens}`)

